<script setup>
import axios from 'axios';
import { onMounted, reactive, ref } from 'vue';
const state = reactive({ kpis: {}, users: [], organizations: [], subscriptions: [], orders: [], rent_orders: [], audit_logs: [] });
const tab = ref('overview'); const error = ref('');
const money = cents => new Intl.NumberFormat('pl-PL', { style: 'currency', currency: 'PLN' }).format(Number(cents || 0) / 100);
async function load() { try { Object.assign(state, (await axios.get('/api/admin/overview')).data); } catch (e) { error.value = e.response?.data?.message || 'Brak dostępu.'; } }
async function toggleUser(user) { await axios.patch(`/api/admin/users/${user.public_id}`, { is_active: !user.is_active }); await load(); }
async function updateOrg(org) { const plan = window.prompt('Plan: free, growth lub pro', org.plan?.code || 'free'); const status = window.prompt('Status: active lub suspended', org.status); if (!plan || !status) return; await axios.patch(`/api/admin/organizations/${org.public_id}`, { plan, status, plan_expires_at: null }); await load(); }
onMounted(load);
</script>
<template><div class="dashboard-shell admin-theme"><aside class="app-sidebar"><a class="app-brand" href="/"><span class="brand-mark">L</span><span>LokalPay Admin</span></a><nav><button v-for="item in [['overview','bi-speedometer2','Przegląd'],['users','bi-people','Użytkownicy'],['organizations','bi-buildings','Organizacje'],['subscriptions','bi-credit-card','Subskrypcje'],['orders','bi-cash-stack','Zamówienia'],['audit','bi-shield-check','Audyt']]" :class="{active:tab===item[0]}" @click="tab=item[0]"><i :class="`bi ${item[1]}`"></i>{{ item[2] }}</button></nav></aside><main class="app-main"><header class="app-topbar"><div><small>SUPER ADMINISTRATOR</small><h1>Centrum platformy</h1></div><span class="avatar">SA</span></header><div v-if="error" class="alert alert-danger">{{ error }}</div><section v-if="tab==='overview'" class="kpi-grid"><article><small>Użytkownicy</small><strong>{{ state.kpis.users }}</strong></article><article><small>Organizacje</small><strong>{{ state.kpis.organizations }}</strong></article><article><small>Aktywne subskrypcje</small><strong>{{ state.kpis.active_subscriptions }}</strong></article><article><small>Sprzedaż SaaS</small><strong>{{ money(state.kpis.paid_saas_cents) }}</strong></article></section><article v-if="tab==='users'" class="panel-card table-responsive"><table class="table"><thead><tr><th>Użytkownik</th><th>E-mail</th><th>Rola</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="u in state.users"><td>{{ u.name }}</td><td>{{ u.email }}</td><td>{{ u.is_super_admin?'super_admin':'user' }}</td><td>{{ u.is_active?'aktywny':'zawieszony' }}</td><td><button class="btn btn-sm btn-outline-danger" @click="toggleUser(u)">{{ u.is_active?'Zawieś':'Aktywuj' }}</button></td></tr></tbody></table></article><article v-if="tab==='organizations'" class="panel-card table-responsive"><table class="table"><thead><tr><th>Nazwa</th><th>Właściciel</th><th>Plan</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="o in state.organizations"><td>{{ o.name }}</td><td>{{ o.owner?.email }}</td><td>{{ o.plan?.name }}</td><td>{{ o.status }}</td><td><button class="btn btn-sm btn-outline-primary" @click="updateOrg(o)">Zmień</button></td></tr></tbody></table></article><article v-if="tab==='subscriptions'" class="panel-card table-responsive"><table class="table"><thead><tr><th>Organizacja</th><th>Plan</th><th>Operator</th><th>Status</th><th>Koniec okresu</th></tr></thead><tbody><tr v-for="s in state.subscriptions"><td>{{ s.organization?.name }}</td><td>{{ s.plan?.name }}</td><td>{{ s.provider }}</td><td>{{ s.status }}</td><td>{{ s.current_period_end }}</td></tr></tbody></table></article><article v-if="tab==='orders'" class="panel-card table-responsive"><h2>Zamówienia planów</h2><table class="table"><thead><tr><th>ID</th><th>Organizacja</th><th>Plan</th><th>Operator</th><th>Kwota</th><th>Status</th></tr></thead><tbody><tr v-for="o in state.orders"><td>{{ o.public_id }}</td><td>{{ o.organization?.name }}</td><td>{{ o.plan?.name }}</td><td>{{ o.provider }}</td><td>{{ money(o.amount_cents) }}</td><td>{{ o.status }}</td></tr></tbody></table><h2 class="mt-5">Zamówienia czynszowe</h2><table class="table"><thead><tr><th>ID</th><th>Organizacja</th><th>Nieruchomość</th><th>Operator</th><th>Kwota</th><th>Status</th></tr></thead><tbody><tr v-for="o in state.rent_orders"><td>{{ o.public_id }}</td><td>{{ o.organization?.name }}</td><td>{{ o.obligation?.property?.name }}</td><td>{{ o.provider }}</td><td>{{ money(o.amount_cents) }}</td><td>{{ o.status }}</td></tr></tbody></table></article><article v-if="tab==='audit'" class="panel-card table-responsive"><table class="table"><thead><tr><th>Data</th><th>Akcja</th><th>Obiekt</th><th>IP</th></tr></thead><tbody><tr v-for="a in state.audit_logs"><td>{{ a.created_at }}</td><td>{{ a.action }}</td><td>{{ a.subject_type }} #{{ a.subject_id }}</td><td>{{ a.ip_address }}</td></tr></tbody></table></article></main></div></template>
